 for(i=0;i<36;i++){var a=i*10*r,l=i%9===0?13:i%3===0?8:4;g+='<path d="M'+(cx+(R-l)*Math.sin(a))+' '+(cy-(R-l)*Math.cos(a))+'L'+(cx+R*Math.sin(a))+' '+(cy-R*Math.cos(a))+'" stroke-opacity=".6" stroke-width="1.5"/>'}
